class Account:
    def __init__(self, bal): self.bal = bal
    def withdraw(self, amt):
        if self.bal < amt: raise ValueError("잔액 부족")
        self.bal -= amt

def deposit_first(krw, usd):
    usd.bal += 1          # 1) 1달러 입금
    usd.withdraw(1)       # 그 사이 카드 결제
    try: krw.withdraw(1300)   # 2) 원화 출금 실패
    except ValueError:
        try: usd.withdraw(1)  # 3) 보상: 1달러 회수
        except ValueError as e: return f"보상 실패 - {e}, 은행이 1달러 손해"

def withdraw_first(krw, usd):
    try: krw.withdraw(1300)
    except ValueError: return "환전 실패(아무것도 안 움직임)"
    usd.bal += 1

print(deposit_first(Account(0), Account(0)))   # 보상 실패 - 잔액 부족, 은행이 1달러 손해
print(withdraw_first(Account(0), Account(0)))  # 환전 실패(아무것도 안 움직임)
